// ── Layout thrashing: BAD pattern ────────────────────────────
function badResize(elements) {
  elements.forEach(el => {
    // READ forces layout flush
    const width = el.offsetWidth;         // browser must layout now!
    // WRITE invalidates layout again
    el.style.width = (width * 2) + 'px';  // invalidates layout
    // Next iteration: READ again → forces another layout flush
  });
  // N elements = N forced synchronous layouts
}

// ── Batching reads and writes: GOOD pattern ───────────────────
function goodResize(elements) {
  // Phase 1: batch all reads
  const widths = elements.map(el => el.offsetWidth);

  // Phase 2: batch all writes
  elements.forEach((el, i) => {
    el.style.width = (widths[i] * 2) + 'px';
  });
  // Only one layout calculation needed
}

// ── Use requestAnimationFrame to sync with render frames ──────
function animateWithRAF(el, targetX) {
  let startTime = null;
  const duration = 300;
  const startX = el.getBoundingClientRect().left;

  function step(timestamp) {
    if (!startTime) startTime = timestamp;
    const progress = Math.min((timestamp - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic

    // transform stays on compositor thread — no layout or paint
    el.style.transform = `translateX(${(targetX - startX) * eased}px)`;

    if (progress < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

// ── Measuring rendering performance ──────────────────────────
const obs = new PerformanceObserver(list => {
  list.getEntries().forEach(entry => {
    if (entry.duration > 50) {
      console.warn(`Long task: ${entry.duration.toFixed(1)}ms`, entry);
    }
  });
});
obs.observe({ type: 'longtask', buffered: true });

