// ── CSS properties and which pipeline stages they trigger ─────
//
// LAYOUT + PAINT + COMPOSITE (most expensive):
//   width, height, padding, margin, border, top, left, right,
//   bottom, font-size, font-family, display, position,
//   flex-*, grid-*, adding/removing DOM nodes
//
// PAINT + COMPOSITE (medium cost, no layout):
//   color, background-color, border-color, box-shadow,
//   outline, text-decoration, background-image,
//   visibility (but not display)
//
// COMPOSITE ONLY (cheapest — runs on GPU thread):
//   transform (translate, scale, rotate)
//   opacity
//   filter (on promoted layer)
//   backdrop-filter

// ── Layout-triggering DOM properties (force sync layout) ──────
const LAYOUT_READS = [
  'offsetTop', 'offsetLeft', 'offsetWidth', 'offsetHeight',
  'scrollTop', 'scrollLeft', 'scrollWidth', 'scrollHeight',
  'clientTop', 'clientLeft', 'clientWidth', 'clientHeight',
  'getComputedStyle()',    // reads ALL computed styles
  'getBoundingClientRect()',
  'getClientRects()',
];
// Reading any of these after a DOM write = forced synchronous layout

// ── Layers and will-change ────────────────────────────────────
// Elements get promoted to their own compositor layer when:
//   - will-change: transform/opacity is set
//   - transform: translateZ(0) / translate3d(0,0,0) (hack)
//   - position: fixed/sticky
//   - <video>, <canvas>, <iframe>
//
// Trade-off: each layer uses GPU memory (~texture RAM)
// Don't promote everything — only elements being animated

// ── ResizeObserver: observe layout changes without polling ────
const ro = new ResizeObserver(entries => {
  for (const entry of entries) {
    const { width, height } = entry.contentRect;
    console.log(`Element resized: ${width}x${height}`);
  }
